private void pop(String descriptor) {
    if (descriptor.startsWith("(")) {
        // Method descriptor
        int argCount = 0;
        for (int i = 1; i < descriptor.length(); i++) {
            if (descriptor.charAt(i) == ')') {
                break;
            }
            argCount++;
        }
        for (int i = 0; i < argCount; i++) {
            outputFrame.pop();
        }
    } else {
        // Type descriptor
        while (!outputFrame.isEmpty() && outputFrame.peek().getType().equals(descriptor)) {
            outputFrame.pop();
        }
    }
}

