public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantInfo constantInfo = constantPool.get(i);
        if (constantInfo instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo constantNameAndTypeInfo = (ConstantNameAndTypeInfo) constantInfo;
            if (constantNameAndTypeInfo.getName().equals(name) && constantNameAndTypeInfo.getDescriptor().equals(descriptor)) {
                return i;
            }
        }
    }

    // If we reach this point, the constant pool does not contain a similar item, so we need to create a new one
    ConstantNameAndTypeInfo constantNameAndTypeInfo = new ConstantNameAndTypeInfo();
    constantNameAndTypeInfo.setName(name);
    constantNameAndTypeInfo.setDescriptor(descriptor);
    constantPool.add(constantNameAndTypeInfo);
    return constantPool.size() - 1;
}

