public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Create a new bipartite graph
    Graph<V, E> bipartiteGraph = new Graph<>(target.getNumVertices(), target.getNumVertices());

    // Add all vertices from the target graph to the bipartite graph
    for (V vertex : target.getVertices()) {
        bipartiteGraph.addVertex(vertex);
    }

    // Add all edges from the target graph to the bipartite graph
    for (E edge : target.getEdges()) {
        bipartiteGraph.addEdge(edge);
    }

    // Add a new vertex to the bipartite graph for each key in the result map
    for (String key : resultMap.keySet()) {
        bipartiteGraph.addVertex(resultMap.get(key));
    }

    // Add a new edge to the bipartite graph for each key in the result map
    for (String key : resultMap.keySet()) {
        bipartiteGraph.addEdge(resultMap.get(key), resultMap.get(key));
    }

    // Return the bipartite graph
    return bipartiteGraph;
}

