public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check if the name is already abbreviated
    if (nameStart + 1 < buf.length() && buf.charAt(nameStart + 1) == '.') {
        return;
    }

    // Find the first letter of the name
    int firstLetterIndex = nameStart;
    while (firstLetterIndex < buf.length() && !Character.isLetter(buf.charAt(firstLetterIndex))) {
        firstLetterIndex++;
    }

    // Find the last letter of the name
    int lastLetterIndex = nameStart;
    while (lastLetterIndex >= 0 && !Character.isLetter(buf.charAt(lastLetterIndex))) {
        lastLetterIndex--;
    }

    // Abbreviate the name
    buf.replace(firstLetterIndex, lastLetterIndex + 1, buf.substring(firstLetterIndex, lastLetterIndex + 1).toUpperCase());
}

